# The rule: for each hollow rectangular frame, fill interior cells based on:
# - odd interior side → fill with 7
# - even interior side → fill with 2

def solve_grid(test_input):
    """Apply the transformation rule to the test grid"""
    rows = len(test_input)
    cols = len(test_input[0])
    output = [row[:] for row in test_input]  # Deep copy

    # Find all hollow frames and fill their interiors
    for r1 in range(rows):
        for c1 in range(cols):
            for r2 in range(r1+2, rows):
                for c2 in range(c1+2, cols):
                    bc = test_input[r1][c1]

                    # Check if valid box
                    is_box = True

                    # Top and bottom borders
                    if not all(test_input[r1][c] == bc for c in range(c1, c2+1)):
                        is_box = False
                    if not all(test_input[r2][c] == bc for c in range(c1, c2+1)):
                        is_box = False
                    # Left and right borders  
                    if not all(test_input[r][c1] == bc for r in range(r1, r2+1)):
                        is_box = False
                    if not all(test_input[r][c2] == bc for r in range(r1, r2+1)):
                        is_box = False

                    if not is_box:
                        continue

                    # Check interior - must not contain border color
                    has_border_color_in_interior = False
                    for rr in range(r1+1, r2):
                        for cc in range(c1+1, c2):
                            if test_input[rr][cc] == bc:
                                has_border_color_in_interior = True
                                break
                        if has_border_color_in_interior:
                            break

                    if has_border_color_in_interior:
                        continue

                    # Fill interior based on parity of interior size
                    inner_h = r2 - r1 - 1
                    inner_w = c2 - c1 - 1

                    # Take minimum side for the fill decision
                    side = min(inner_h, inner_w)
                    fill_val = 7 if side % 2 == 1 else 2

                    # Apply fill to interior
                    for rr in range(r1+1, r2):
                        for cc in range(c1+1, c2):
                            if test_input[rr][cc] != bc:  # Don't overwrite border
                                output[rr][cc] = fill_val

    return output

